# Load all demo pairs from session log
import os, glob, re, json

session_dir = os.environ['RLM_SESSION_DIR']
session_file = os.path.join(session_dir, '../../sessions/' + os.path.basename(session_dir) + '.jsonl')

def load_grids():
    try:
        with open(session_file, 'r') as f:
            content = f.read()
    except:
        return {}

    grids = {}
    # Find pattern: "Demo pair N input", "Demo pair N output", "Test input"
    for task_id in ['task-004cd24b']:
        pattern = rf'{re.escape(task_id)} (Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):'
        for m in re.finditer(pattern, content):
            full_key = m.group(1)
            height, width = int(m.group(2)), int(m.group(3))
            # Get the grid rows following this
            start = m.end()
            rows = []
            for line in content[start:].split('\n')[:height]:
                row = [int(x) for x in line.split()]
                if row:
                    rows.append(row)
            if len(rows) == height and all(len(row) == width for row in rows):
                if full_key == 'Test input':
                    grids['Test'] = rows
                else:
                    grids[full_key] = rows
    return grids

grids = load_grids()
for k, v in sorted(grids.items()):
    print(f"{k}: {len(v)}x{len(v[0]) if v else 0}")

